public SecurityFilterChain securityFilterChain(HttpSecurity http, CorsConfigurationSource corsConfigurationSource,
            org.springframework.security.web.csrf.CookieCsrfTokenRepository csrfTokens) throws Exception {
        http
                .cors(cors -> cors.configurationSource(corsConfigurationSource))
                .csrf(csrf -> csrf
                        .ignoringRequestMatchers("/ws/**")
                        .csrfTokenRepository(csrfTokens)
                        // JWT authentication runs on every request; rotate CSRF only at explicit login/logout.
                        .sessionAuthenticationStrategy(new org.springframework.security.web.authentication.session.NullAuthenticatedSessionStrategy())
                        .csrfTokenRequestHandler(new org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler()))
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        // Staff pages require an authenticated staff JWT.
                        .requestMatchers("/admin", "/admin/**").hasRole("ADMIN")
                        .requestMatchers("/cashier", "/cashier/**").hasAnyRole("ADMIN", "CASHIER")
                        .requestMatchers("/kitchen", "/kitchen/**").hasAnyRole("ADMIN", "KITCHEN")
                        .requestMatchers("/staff", "/staff/**").hasAnyRole("ADMIN", "CASHIER", "KITCHEN")
                        // 1. Static resources, pages & websocket
                        .requestMatchers(
                                "/",
                                "/menu",
                                "/marketplace",
                                "/cart",
                                "/orders",
                                "/order-confirmation",
                                "/profile",
                                "/login",
                                "/error",
                                "/static/**",
                                "/css/**",
                                "/js/**",
                                "/images/**",
                                "/ws/**",
                                "/actuator/health",
                                "/actuator/info"
                        ).permitAll()
                        // 2. Role-based staff routes
                        // Listing customer history is account-only, including when a table QR exists.
                        .requestMatchers(org.springframework.http.HttpMethod.GET,
                                "/api/v1/customer/orders", "/api/v1/customer/orders/*")
                            .hasAnyRole("CUSTOMER", "CASHIER", "ADMIN", "VENDOR", "MANAGER", "SHIPPER")
                        // The public table list exposes all table QR secrets and must not be public.
                        .requestMatchers(org.springframework.http.HttpMethod.GET, "/api/v1/tables")
                            .hasAnyRole("ADMIN", "CASHIER")
                        .requestMatchers("/api/v1/admin/**").hasRole("ADMIN")
                        .requestMatchers("/api/v1/cashier/**").hasAnyRole("ADMIN", "CASHIER")
                        .requestMatchers("/api/v1/kitchen/**").hasAnyRole("ADMIN", "KITCHEN")
                        .requestMatchers("/api/v1/inventory/**").hasAnyRole("ADMIN", "KITCHEN", "CASHIER")
                        // 3. Public, Customer & Guest routes
                        .requestMatchers(
                                "/api/v1/auth/**",
                                "/api/v1/public/**",
                                "/api/v1/catalog/**",
                                "/api/v1/tables/**",
                                "/api/v1/table-sessions/**",
                                "/api/v1/orders/**",
                                "/api/v1/customer/**"
                        ).permitAll()
                        // Everything else authenticated
                        .anyRequest().authenticated()
                )
                .exceptionHandling(ex -> ex
                        .authenticationEntryPoint((request, response, authException) -> {
                            String uri = request.getRequestURI();
                            boolean staffPage = uri.equals("/merchant") || uri.equals("/admin") || uri.startsWith("/admin/")
                                    || uri.equals("/cashier") || uri.startsWith("/cashier/")
                                    || uri.equals("/kitchen") || uri.startsWith("/kitchen/")
                                    || uri.equals("/staff") || uri.startsWith("/staff/");

                            if (staffPage) {
                                response.sendRedirect("/login?redirect=" + uri);
                                return;
                            }
                            response.sendError(403);
                        })
                        .accessDeniedHandler((request, response, accessDeniedException) -> {
                    Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
                    String uri = request.getRequestURI();
                    boolean staffPage = uri.equals("/merchant") || uri.equals("/admin") || uri.startsWith("/admin/")
                            || uri.equals("/cashier") || uri.startsWith("/cashier/")
                            || uri.equals("/kitchen") || uri.startsWith("/kitchen/")
                            || uri.equals("/staff") || uri.startsWith("/staff/");
                    boolean anonymous = authentication == null || authentication instanceof AnonymousAuthenticationToken;

                    if (staffPage && anonymous) {
                        response.sendRedirect("/login?redirect=" + uri);
                        return;
                    }
                    response.sendError(403);
                }))
                .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }

JwtService.generateToken.code:
public String generateToken(Account account) {
        try {
            Instant now = Instant.now();
            Instant exp = now.plus(ttlMinutes, ChronoUnit.MINUTES);

            Map<String, Object> header = Map.of("alg", "HS256", "typ", "JWT");
            Map<String, Object> claims = new HashMap<>();
            claims.put("sub", String.valueOf(account.getId()));
            claims.put("email", account.getEmail());
            claims.put("role", account.getRole().name());
            claims.put("tokenVersion", account.getTokenVersion());
            claims.put("iss", issuer);
            claims.put("aud", audience);
            claims.put("iat", now.getEpochSecond());
            claims.put("exp", exp.getEpochSecond());

            String encodedHeader = base64UrlEncode(objectMapper.writeValueAsBytes(header));
            String encodedPayload = base64UrlEncode(objectMapper.writeValueAsBytes(claims));
            String dataToSign = encodedHeader + "." + encodedPayload;

            byte[] signature = sign(dataToSign.getBytes(StandardCharsets.UTF_8));
            String encodedSignature = base64UrlEncode(signature);

            return dataToSign + "." + encodedSignature;
        } catch (Exception e) {
            throw new RuntimeException("Lỗi sinh JWT token", e);
        }
    }

JwtService.validateAndExtractClaims.code:
public Map<String, Object> validateAndExtractClaims(String token) {
        if (token == null || token.isBlank()) return null;
        String[] parts = token.split("\\.");
        if (parts.length != 3) return null;

        try {
            String dataToSign = parts[0] + "." + parts[1];
            byte[] expectedSig = sign(dataToSign.getBytes(StandardCharsets.UTF_8));
            byte[] actualSig = base64UrlDecode(parts[2]);

            if (!MessageDigest.isEqual(expectedSig, actualSig)) {
                return null;
            }

            byte[] payloadBytes = base64UrlDecode(parts[1]);
            Map<String, Object> claims = objectMapper.readValue(payloadBytes, new TypeReference<>() {});

            long exp = ((Number) claims.get("exp")).longValue();
            if (Instant.now().getEpochSecond() > exp) {
                return null;
            }

            if (!issuer.equals(claims.get("iss")) || !audience.equals(claims.get("aud"))) {
                return null;
            }

            return claims;
        } catch (Exception e) {
            log.debug("Lỗi xác thực JWT: {}", e.getMessage());
            return null;
        }
    }

