TableController.getTableContext.code:
public ResponseEntity<ApiResponse<TableDto.TableContextResponse>> getTableContext(
            @RequestParam(value = "qrCode", required = false) String qrCode,
            @RequestParam(value = "table", required = false) String tableParam,
            @AuthenticationPrincipal CurrentActor actor) {

        if (qrCode == null || qrCode.isBlank()) {
            // Never turn a predictable table ID into a QR/session access proof for an anonymous visitor.
            if (tableParam != null && !tableParam.isBlank() &&
                    (actor == null || !(actor.hasRole(vn.edu.ute.milktea.entity.account.Role.ADMIN) ||
                                        actor.hasRole(vn.edu.ute.milktea.entity.account.Role.CASHIER)))) {
                throw vn.edu.ute.milktea.common.BusinessException.forbidden(
                        vn.edu.ute.milktea.common.ErrorCode.ACCESS_DENIED,
                        "Hãy quét mã bàn hợp lệ để tiếp tục");
            }
            if (tableParam != null && !tableParam.isBlank()) {
                DiningTable t = null;
                try {
                    Long id = Long.parseLong(tableParam.trim());
                    t = tableRepository.findById(id).orElse(null);
                } catch (NumberFormatException ignored) {}
                if (t == null) {
                    t = tableRepository.findByName(tableParam.trim()).orElse(null);
                }
                if (t != null) {
                    qrCode = t.getQrCode();
                }
            }
        }
        return ResponseEntity.ok(ApiResponse.ok(tableContextService.readByQr(qrCode)));
    }

