public void updateSettings(SettingsDto.UpdateSettingsRequest request, Long adminId) {
        Account admin = adminId != null ? accountRepository.findById(adminId).orElse(null) : null;

        GlobalSettings settings = settingsRepository.findById(1)
                .orElseGet(() -> GlobalSettings.builder()
                        .id(1)
                        .build());

        settings.setShopName(request.getShopName());
        settings.setAddress(request.getAddress());
        settings.setBankName(request.getBankName());
        settings.setBankAccountNumber(request.getBankAccountNumber());
        settings.setBankAccountHolder(request.getBankAccountHolder());

        String type = request.getDiscountType();
        if (type == null || type.isBlank()) {
            type = "PERCENT";
        }
        type = type.trim().toUpperCase();
        if (!"PERCENT".equals(type) && !"FIXED_AMOUNT".equals(type)) {
            type = "PERCENT";
        }

        BigDecimal val = request.getDiscountValue();
        if (val == null) {
            val = request.getDiscountPercent() != null ? request.getDiscountPercent() : BigDecimal.ZERO;
        }

        if ("PERCENT".equals(type)) {
            if (val.compareTo(BigDecimal.ZERO) < 0 || val.compareTo(new BigDecimal("100")) > 0) {
                throw vn.edu.ute.milktea.common.BusinessException.badRequest(
                        vn.edu.ute.milktea.common.ErrorCode.VALIDATION_FAILED,
                        "Phần trăm giảm giá phải từ 0% đến 100%");
            }
            settings.setDiscountType("PERCENT");
            settings.setDiscountPercent(val);
            settings.setDiscountValue(val);
        } else {
            if (val.compareTo(BigDecimal.ZERO) < 0) {
                throw vn.edu.ute.milktea.common.BusinessException.badRequest(
                        vn.edu.ute.milktea.common.ErrorCode.VALIDATION_FAILED, "Số tiền giảm cố định không được âm");
            }
            settings.setDiscountType("FIXED_AMOUNT");
            settings.setDiscountValue(val);
            settings.setDiscountPercent(BigDecimal.ZERO);
        }

        settings.setModifiedBy(admin);
        settings.setModifiedAt(Instant.now());

        settingsRepository.save(settings);

        realtimeEventPublisher.publishAfterCommit("/topic/admin", "SETTINGS_CHANGED", "1", null, "1",
                java.util.Map.of("shopName", settings.getShopName()));
        realtimeEventPublisher.publishAfterCommit("/topic/cashier", "SETTINGS_CHANGED", "1", null, "1",
                java.util.Map.of("shopName", settings.getShopName()));
    }

OtpService.generateAndSaveOtp.code:
public GeneratedOtp generateAndSaveOtp(String email, String purpose, int ttlMinutes) {
        if (otpSecret == null || otpSecret.length() < 32) {
            log.error("Thiếu cấu hình OTP_SECRET: cần khóa bí mật tối thiểu 32 ký tự");
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED,"Chưa cấu hình dịch vụ xác thực email. Vui lòng liên hệ quản trị viên.");
        }
        String cleanEmail = email.trim().toLowerCase();
        Instant now = Instant.now();

        // 1. Kiểm tra cooldown chống gửi dồn dập / spam
        var latestActiveOpt = otpRepository.findTopByEmailAndPurposeOrderByCreatedAtDesc(
                cleanEmail, purpose);

        if (latestActiveOpt.isPresent()) {
            EmailVerificationOtp latest = latestActiveOpt.get();
            long elapsedSeconds = Duration.between(latest.getLastSentAt(), now).toSeconds();
            if (elapsedSeconds < cooldownSeconds) {
                long waitSeconds = cooldownSeconds - elapsedSeconds;
                throw BusinessException.badRequest(
                        ErrorCode.AUTH_RATE_LIMITED,
                        "Vui lòng đợi " + waitSeconds + " giây trước khi yêu cầu gửi lại mã xác thực mới."
                );
            }
        }

        // 2. Vô hiệu hóa tất cả mã cũ chưa dùng của email và purpose này
        List<EmailVerificationOtp> oldOtps = otpRepository.findAllByEmailAndPurposeAndRevokedAtIsNullAndUsedAtIsNull(
                cleanEmail, purpose);
        for (EmailVerificationOtp old : oldOtps) {
            old.setRevokedAt(now);
        }
        if (!oldOtps.isEmpty()) {
            otpRepository.saveAll(oldOtps);
        }

        // 3. Sinh OTP 6 chữ số ngẫu nhiên an toàn bằng SecureRandom
        int number = secureRandom.nextInt(1_000_000);
        String rawOtp = String.format("%06d", number);

        // 4. Sinh salt ngẫu nhiên 16 bytes cho từng bản ghi
        byte[] saltBytes = new byte[16];
        secureRandom.nextBytes(saltBytes);
        String salt = HexFormat.of().formatHex(saltBytes);

        // 5. Băm OTP bằng HMAC-SHA256 có secret và salt gắn liền email + purpose
        String otpHash = computeHmacHash(rawOtp, salt, cleanEmail, purpose);

        EmailVerificationOtp otpEntity = EmailVerificationOtp.builder()
                .email(cleanEmail)
                .otpHash(otpHash)
                .salt(salt)
                .purpose(purpose)
                .expiresAt(now.plus(ttlMinutes, ChronoUnit.MINUTES))
                .attempts(0)
                .maxAttempts(defaultMaxAttempts)
                .lastSentAt(now)
                .createdAt(now)
                .build();

        EmailVerificationOtp saved = otpRepository.save(otpEntity);
        return new GeneratedOtp(rawOtp, saved);
    }

OtpService.verifyOtp.code:
public void verifyOtp(String email, String purpose, String rawOtp) {
        String cleanEmail = email.trim().toLowerCase();
        String cleanOtp = rawOtp != null ? rawOtp.trim() : "";

        if (cleanOtp.length() != 6 || !cleanOtp.matches("^\\d{6}$")) {
            throw BusinessException.badRequest(ErrorCode.AUTH_OTP_INVALID, "Mã xác thực phải gồm đúng 6 chữ số.");
        }

        var otpOpt = otpRepository.findTopByEmailAndPurposeAndRevokedAtIsNullAndUsedAtIsNullOrderByCreatedAtDesc(
                cleanEmail, purpose);

        if (otpOpt.isEmpty()) {
            throw BusinessException.badRequest(
                    ErrorCode.AUTH_OTP_INVALID,
                    "Không tìm thấy mã xác thực hợp lệ hoặc mã đã bị hủy. Vui lòng yêu cầu mã mới."
            );
        }

        EmailVerificationOtp otp = otpOpt.get();
        Instant now = Instant.now();

        // Kiểm tra hết hạn
        if (!otp.getExpiresAt().isAfter(now)) {
            otp.setRevokedAt(now);
            otpRepository.save(otp);
            throw BusinessException.badRequest(
                    ErrorCode.AUTH_TOKEN_EXPIRED,
                    "Mã xác thực đã hết hạn. Vui lòng nhấn 'Gửi lại mã' để nhận mã mới."
            );
        }

        // Kiểm tra số lần thử tối đa
        if (otp.getAttempts() >= otp.getMaxAttempts()) {
            otp.setRevokedAt(now);
            otpRepository.save(otp);
            throw BusinessException.badRequest(
                    ErrorCode.AUTH_OTP_INVALID,
                    "Mã xác thực đã bị khóa do thử sai quá " + otp.getMaxAttempts() + " lần. Vui lòng yêu cầu gửi lại mã mới."
            );
        }

        // So sánh HMAC Hash
        String expectedHash = computeHmacHash(cleanOtp, otp.getSalt(), cleanEmail, purpose);
        if (!java.security.MessageDigest.isEqual(expectedHash.getBytes(StandardCharsets.UTF_8), otp.getOtpHash().getBytes(StandardCharsets.UTF_8))) {
            int newAttempts = otp.getAttempts() + 1;
            otp.setAttempts(newAttempts);
            if (newAttempts >= otp.getMaxAttempts()) {
                otp.setRevokedAt(now);
            }
            otpRepository.save(otp);

            int remaining = Math.max(0, otp.getMaxAttempts() - newAttempts);
            if (remaining > 0) {
                throw BusinessException.badRequest(
                        ErrorCode.AUTH_OTP_INVALID,
                        "Mã xác thực không chính xác. Bạn còn " + remaining + " lần thử."
                );
            } else {
                throw BusinessException.badRequest(
                        ErrorCode.AUTH_OTP_INVALID,
                        "Mã xác thực đã bị khóa do nhập sai quá " + otp.getMaxAttempts() + " lần. Vui lòng yêu cầu mã mới."
                );
            }
        }

        // Khớp mã -> đánh dấu đã dùng
        otp.setUsedAt(now);
        otpRepository.save(otp);
    }

OtpService.computeHmacHash.code:
private String computeHmacHash(String rawOtp, String salt, String email, String purpose) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec secretKeySpec = new SecretKeySpec(otpSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(secretKeySpec);
            String payload = salt + ":" + rawOtp + ":" + email + ":" + purpose;
            byte[] hashBytes = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hashBytes);
        } catch (Exception e) {
            log.error("Lỗi tính toán HMAC cho OTP: {}", e.getMessage());
            throw new RuntimeException("Lỗi bảo mật khi băm mã OTP", e);
        }
    }

AuthService.login.code:
public AuthDto.AuthResponse login(AuthDto.LoginRequest request) {
        String email = request.getEmail().trim().toLowerCase();
        Account account = accountRepository.findByEmail(email)
                .orElseThrow(() -> BusinessException.unauthorized(
                        ErrorCode.AUTH_INVALID_CREDENTIALS, "Tài khoản hoặc mật khẩu không đúng"));

        // 1. Kiểm tra tài khoản bị admin khóa
        if (!Boolean.TRUE.equals(account.getActive())) {
            throw BusinessException.forbidden(
                    ErrorCode.ACCESS_DENIED, "Tài khoản đã bị tạm khóa. Vui lòng liên hệ ban quản trị.");
        }

        // 2. Kiểm tra mật khẩu
        if (!passwordEncoder.matches(request.getPassword(), account.getPasswordHash())) {
            throw BusinessException.unauthorized(
                    ErrorCode.AUTH_INVALID_CREDENTIALS, "Tài khoản hoặc mật khẩu không đúng");
        }

        // 3. Kiểm tra xác thực email (Tách biệt khỏi trạng thái khóa)
        if (!Boolean.TRUE.equals(account.getEmailVerified())) {
            throw BusinessException.unauthorized(
                    ErrorCode.AUTH_EMAIL_NOT_VERIFIED,
                    "Địa chỉ email chưa được xác thực. Vui lòng xác thực email để kích hoạt tài khoản trước khi đăng nhập.");
        }

        String token = jwtService.generateToken(account);
        return AuthDto.AuthResponse.builder()
                .token(token)
                .user(AuthDto.UserInfo.builder()
                        .id(account.getId())
                        .email(account.getEmail())
                        .fullName(account.getFullName())
                        .phone(account.getPhone())
                        .role(account.getRole())
                        .build())
                .build();
    }

AuthService.register.code:
public AuthDto.RegisterResponse register(AuthDto.RegisterRequest request) {
        String email = request.getEmail().trim().toLowerCase();
        Optional<Account> existingOpt = accountRepository.findByEmailForUpdate(email);

        Account account;
        if (existingOpt.isPresent()) {
            Account existing = existingOpt.get();
            if (Boolean.TRUE.equals(existing.getEmailVerified())) {
                throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED, "Địa chỉ email này đã được sử dụng");
            }
            if (existing.getRole() != Role.CUSTOMER || !Boolean.TRUE.equals(existing.getActive())) {
                throw BusinessException.forbidden(ErrorCode.ACCESS_DENIED, "Tài khoản không thể đăng ký lại qua biểu mẫu công khai");
            }
            // Pending customers can retry after SMTP recovery.
            existing.setPasswordHash(passwordEncoder.encode(request.getPassword()));
            if (request.getFullName() != null && !request.getFullName().isBlank()) {
                existing.setFullName(request.getFullName().trim());
            }
            if (request.getPhone() != null && !request.getPhone().isBlank()) {
                existing.setPhone(request.getPhone().trim());
            }
            account = accountRepository.save(existing);
        } else {
            account = Account.builder()
                    .email(email)
                    .passwordHash(passwordEncoder.encode(request.getPassword()))
                    .fullName(request.getFullName() != null ? request.getFullName().trim() : null)
                    .phone(request.getPhone() != null ? request.getPhone().trim() : null)
                    .role(Role.CUSTOMER) // Khách đăng ký công khai bắt buộc là CUSTOMER
                    .active(true)
                    .emailVerified(false) // Chưa xác thực email
                    .tokenVersion(1L)
                    .createdAt(Instant.now())
                    .build();
            account = accountRepository.save(account);
        }

        // Sinh mã OTP 6 số bảo vệ HMAC-SHA256, hạn 10 phút
        OtpService.GeneratedOtp generated = otpService.generateAndSaveOtp(
                email, EmailVerificationOtp.PURPOSE_REGISTER, 10);

        // Gửi email thật qua SMTP
        mailService.sendRegistrationOtpEmail(email, account.getFullName(), generated.rawOtp(), 10);

        return AuthDto.RegisterResponse.builder()
                .email(email)
                .maskedEmail(MailService.maskEmail(email))
                .message("Tài khoản đang chờ kích hoạt. Mã xác thực 6 chữ số đã được gửi tới email của bạn. Vui lòng nhập mã để kích hoạt tài khoản.")
                .emailVerified(false)
                .cooldownSeconds(60)
                .build();
    }

AuthService.verifyEmail.code:
public String verifyEmail(AuthDto.VerifyEmailRequest request) {
        String email = request.getEmail().trim().toLowerCase();
        Account account = accountRepository.findByEmail(email)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.VALIDATION_FAILED, "Không tìm thấy tài khoản với email này"));

        if (Boolean.TRUE.equals(account.getEmailVerified())) {
            return "Tài khoản của bạn đã được xác thực trước đó. Bạn có thể đăng nhập ngay.";
        }

        // Xác thực mã OTP (kiểm tra hạn dùng, băm HMAC, số lần thử)
        otpService.verifyOtp(email, EmailVerificationOtp.PURPOSE_REGISTER, request.getOtp());

        // Cập nhật trạng thái xác thực email
        // LƯU Ý: Không tự mở khóa nếu tài khoản đang bị admin khóa (active = false)
        account.setEmailVerified(true);
        accountRepository.save(account);

        return "Xác thực email thành công! Bạn có thể đăng nhập vào hệ thống ngay bây giờ.";
    }

AuthService.resendRegisterOtp.code:
public String resendRegisterOtp(String email) {
        String cleanEmail = email.trim().toLowerCase();
        Account account = accountRepository.findByEmailForUpdate(cleanEmail)
                .orElseThrow(() -> BusinessException.notFound(ErrorCode.VALIDATION_FAILED, "Địa chỉ email chưa được đăng ký trong hệ thống"));

        if (Boolean.TRUE.equals(account.getEmailVerified())) {
            throw BusinessException.badRequest(ErrorCode.VALIDATION_FAILED, "Tài khoản đã được xác thực. Bạn có thể đăng nhập ngay.");
        }

        OtpService.GeneratedOtp generated = otpService.generateAndSaveOtp(
                cleanEmail, EmailVerificationOtp.PURPOSE_REGISTER, 10);

        mailService.sendRegistrationOtpEmail(cleanEmail, account.getFullName(), generated.rawOtp(), 10);

        return "Mã xác thực mới đã được gửi tới email " + MailService.maskEmail(cleanEmail) + ". Vui lòng kiểm tra hộp thư.";
    }

