        return vn.edu.ute.milktea.dto.TableDto.TableSessionResponse.builder()
                .sessionId(s.getId())
                .tableId(s.getTable().getId())
                .tableName(s.getTable().getName())
                .status(s.getStatus())
                .openedAt(s.getOpenedAt())
                .closedAt(s.getClosedAt())
                .build();
    }

